func newNodePropertiesSchemaCommand(
	nodePropertiesSchemaGet NodePropertiesSchemaGetHandler,
	nodePropertiesSchemaSet NodePropertiesSchemaSetHandler,
	nodePropertiesSchemaChildren NodePropertiesSchemaChildrenHandler,
) *cobra.Command {
	cmd := &cobra.Command{
		Use:   "schema",
		Short: "Manage node property schemas.",
		Long:  "# Manage shared field definitions\n\nA property **schema** defines the fields shared by sibling Library pages: their\nnames, types, and sort directions. The pages hold their own values. For example,\na directory can define `status` as text and `priority` as a number for its entries.\n\nThe command's target matters: selecting a parent addresses the schema for its\nchildren; selecting a child addresses the schema it shares with its siblings.\nThis is a group-wide structure change, rather than a value change on one page.\n\n## Commands and workflows\n\nA node's property schema is shared with its siblings. `get PARENT` reads the\nchild-property schema on a parent; `children PARENT` updates it. `set CHILD`\nupdates the schema of the selected child and its siblings. These are different scopes: inspect the hierarchy first.\n\nUse `properties set` for values on one page. Schema changes define names, types,\nand sort directions across a group of pages.\n",
		Args:  groupArgs,
		RunE: func(cmd *cobra.Command, args []string) error {
			return cmd.Help()
		},
	}
	cmd.AddCommand(
		newNodePropertiesSchemaGetCommand(nodePropertiesSchemaGet),
		newNodePropertiesSchemaSetCommand(nodePropertiesSchemaSet),
		newNodePropertiesSchemaChildrenCommand(nodePropertiesSchemaChildren),
	)
	return cmd
}
func newNodePropertiesCommand(
	nodePropertiesGet NodePropertiesGetHandler,
	nodePropertiesSet NodePropertiesSetHandler,
	nodePropertiesSchemaGet NodePropertiesSchemaGetHandler,
	nodePropertiesSchemaSet NodePropertiesSchemaSetHandler,
	nodePropertiesSchemaChildren NodePropertiesSchemaChildrenHandler,
) *cobra.Command {
	cmd := &cobra.Command{
		Use:   "properties",
		Short: "Manage node properties.",
		Long:  "# Work with typed page fields\n\n**Properties** turn Library pages into structured records as well as documents.\nFor example, entries in a product catalogue might each have a price, a release\ndate, and an availability field. Properties have names, types, and per-page values.\n\nChildren of the same parent share a **schema**: the field definitions that make\nthose entries comparable in a directory or table view. The values belong to each\npage; changing shared definitions can affect its siblings too.\n\n## Commands and workflows\n\nProperties are typed values on nodes; sibling nodes share field schemas. Use\n`get` before `set` to discover names and types. Use `schema` to change the fields\nshared across siblings or children. For arbitrary JSON use `node meta` instead.\n",
		Args:  groupArgs,
		RunE: func(cmd *cobra.Command, args []string) error {
			return cmd.Help()
		},
	}
	cmd.AddCommand(
		newNodePropertiesGetCommand(nodePropertiesGet),
		newNodePropertiesSetCommand(nodePropertiesSet),
		newNodePropertiesSchemaCommand(
			nodePropertiesSchemaGet,
			nodePropertiesSchemaSet,
			nodePropertiesSchemaChildren,
		),
	)
	return cmd
}
